public SqliteRelayMetadataStore(Path database) {
    try {
        Path file = database.toAbsolutePath().normalize();
        java.nio.file.Files.createDirectories(file.getParent());
        connection = DriverManager.getConnection("jdbc:sqlite:" + file);
        connection.setAutoCommit(true);
        migrate();
    } catch (java.io.IOException | SQLException failure) {
        throw new IllegalStateException("Relay metadata store unavailable", failure);
    }
}

private void migrate() throws SQLException {
    try (var statement = connection.createStatement()) {
        statement.executeUpdate("PRAGMA journal_mode=WAL");
        statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_device (tenant_id TEXT NOT NULL, device_id TEXT NOT NULL, auth_algorithm TEXT NOT NULL, public_key BLOB NOT NULL, roles TEXT NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT, PRIMARY KEY (tenant_id, device_id))");
        statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_host (tenant_id TEXT NOT NULL, host_id TEXT NOT NULL, auth_algorithm TEXT NOT NULL DEFAULT 'ed25519-x509', auth_public_key BLOB NOT NULL DEFAULT X'', noise_key_algorithm TEXT NOT NULL, public_key BLOB NOT NULL, noise_public_key BLOB NOT NULL DEFAULT X'', protocol_version INTEGER NOT NULL, release_version TEXT NOT NULL, registered_at TEXT NOT NULL, PRIMARY KEY (tenant_id, host_id))");
        addColumn(statement, "relay_host", "auth_algorithm TEXT NOT NULL DEFAULT 'ed25519-x509'");
        addColumn(statement, "relay_host", "auth_public_key BLOB NOT NULL DEFAULT X''");
        addColumn(statement, "relay_host", "noise_public_key BLOB NOT NULL DEFAULT X''");
        statement.executeUpdate("DELETE FROM relay_host WHERE length(auth_public_key) = 0 OR length(noise_public_key) = 0");
        statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_invitation (tenant_id TEXT NOT NULL, invitation_id TEXT NOT NULL, issuer_device_id TEXT NOT NULL, host_ids TEXT NOT NULL, secret_hash BLOB NOT NULL, fingerprint TEXT NOT NULL, expires_at TEXT NOT NULL, confirmed_at TEXT, consumed_at TEXT, PRIMARY KEY (tenant_id, invitation_id))");
        statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_grant (tenant_id TEXT NOT NULL, host_id TEXT NOT NULL, device_id TEXT NOT NULL, requested_scopes TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, host_id, device_id))");
    }
}

private static void addColumn(java.sql.Statement statement, String table, String definition) throws SQLException {
    try {
        statement.executeUpdate("ALTER TABLE " + table + " ADD COLUMN " + definition);
    } catch (SQLException alreadyMigrated) {
        String message = alreadyMigrated.getMessage();
        if (message == null || !message.toLowerCase(java.util.Locale.ROOT).contains("duplicate column")) {
            throw alreadyMigrated;
        }
    }
}

