public SqliteRelayMetadataStore(Path database) {
    try {
        Path file = database.toAbsolutePath().normalize();
        RelayDatabaseMigrations.migrate(file);
        connection = DriverManager.getConnection("jdbc:sqlite:" + file);
        connection.setAutoCommit(true);
        try (var statement = connection.createStatement()) {
            statement.executeUpdate("PRAGMA journal_mode=WAL");
            statement.executeUpdate("PRAGMA synchronous=FULL");
            statement.executeUpdate("PRAGMA busy_timeout=5000");
        }
    } catch (io.github.diodeme.ji.storage.sqlite.SqliteMigrationException | SQLException failure) {
        throw new IllegalStateException("Relay metadata store unavailable", failure);
    }
}

